#!/usr/bin/env python3
"""One-shot CI reconciliation for the successful v0.41.63 ledger."""

import base64
import hashlib
from pathlib import Path
import subprocess


ROOT = Path(__file__).resolve().parents[2]
LEDGER = ROOT / "AI_Companion_当前总账.md"
OLD_GIT_BLOB = "9006755f969eaa259dcf278c78f019ea5cb1e103"
NEW_GIT_BLOB = "4a109c4842572d4146f7eab85e3a648c938bd793"
PATCH_B64 = ""


def git_blob_sha(path: Path) -> str:
    payload = path.read_bytes()
    framed = f"blob {len(payload)}".encode() + b'\0' + payload
    return hashlib.sha1(framed).hexdigest()


def main() -> None:
    actual = git_blob_sha(LEDGER)
    if actual != OLD_GIT_BLOB:
        raise SystemExit(f"unexpected ledger base: {actual}")
    subprocess.run(
        ["git", "apply", "--whitespace=nowarn", "-"],
        cwd=ROOT,
        input=base64.b64decode(PATCH_B64),
        check=True,
    )
    actual = git_blob_sha(LEDGER)
    if actual != NEW_GIT_BLOB:
        raise SystemExit(f"unexpected reconciled ledger: {actual}")
    print(f"v0.41.63 successful-build ledger reconciled: {actual}")


if __name__ == "__main__":
    main()
